"use client";

import {
  FormEvent,
  useEffect,
  useState,
} from "react";

export type ConnectionType =
  | "power"
  | "communication"
  | "sensor_data"
  | "control"
  | "mechanical"
  | "thermal";

export interface ConnectionData {
  type: ConnectionType;
  protocol: string;
  description: string;

  sourceInterfaceId?: string;
  targetInterfaceId?: string;
}

interface InterfaceOption {
  id: string;
  name: string;
  type: string;
}

interface ConnectionModalProps {
  open: boolean;

  sourceName: string;
  targetName: string;

  sourceInterfaces: InterfaceOption[];
  targetInterfaces: InterfaceOption[];

  initialData?: ConnectionData;

  initialSourceInterfaceId?: string;
  initialTargetInterfaceId?: string;

  onClose: () => void;

  onSubmit: (
    data: ConnectionData
  ) => void;
}

export default function ConnectionModal({
  open,
  sourceName,
  targetName,
  sourceInterfaces,
  targetInterfaces,
  initialData,
  initialSourceInterfaceId,
  initialTargetInterfaceId,
  onClose,
  onSubmit,
}: ConnectionModalProps) {
  const [type, setType] =
    useState<ConnectionType>(
      "communication"
    );

  const [protocol, setProtocol] =
    useState("");

  const [description, setDescription] =
    useState("");

  const [
    sourceInterfaceId,
    setSourceInterfaceId,
  ] = useState("");

  const [
    targetInterfaceId,
    setTargetInterfaceId,
  ] = useState("");

  useEffect(() => {
    if (!open) return;

    setType(
      initialData?.type ??
        "communication"
    );

    setProtocol(
      initialData?.protocol ?? ""
    );

    setDescription(
      initialData?.description ?? ""
    );

    setSourceInterfaceId(
      initialSourceInterfaceId ??
        initialData?.sourceInterfaceId ??
        sourceInterfaces[0]?.id ??
        ""
    );

    setTargetInterfaceId(
      initialTargetInterfaceId ??
        initialData?.targetInterfaceId ??
        targetInterfaces[0]?.id ??
        ""
    );
  }, [
    open,
    initialData,
    initialSourceInterfaceId,
    initialTargetInterfaceId,
    sourceInterfaces,
    targetInterfaces,
  ]);

  if (!open) return null;

  const isEditing =
    Boolean(initialData);

  function handleSubmit(
    event: FormEvent
  ) {
    event.preventDefault();

    onSubmit({
      type,
      protocol:
        protocol.trim(),
      description:
        description.trim(),
      sourceInterfaceId,
      targetInterfaceId,
    });
  }

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 p-4 backdrop-blur-sm"
      onMouseDown={(event) => {
        if (
          event.target ===
          event.currentTarget
        ) {
          onClose();
        }
      }}
    >
      <div className="w-full max-w-lg rounded-2xl border border-white/10 bg-[#111419] shadow-2xl">

        <div className="flex items-center justify-between border-b border-white/10 px-6 py-4">
          <div>
            <h2 className="text-lg font-semibold text-white">
              {isEditing
                ? "Edit Connection"
                : "Define Connection"}
            </h2>

            <p className="mt-1 text-xs text-white/40">
              {sourceName} →{" "}
              {targetName}
            </p>
          </div>

          <button
            type="button"
            onClick={onClose}
            className="rounded-lg px-2 py-1 text-white/40 hover:bg-white/10 hover:text-white"
          >
            ×
          </button>
        </div>

        <form
          onSubmit={handleSubmit}
          className="space-y-5 p-6"
        >
          {/* Source interface */}

          <div>
            <label className="mb-2 block text-sm text-white/60">
              Source Interface
            </label>

            <select
              value={
                sourceInterfaceId
              }
              onChange={(event) =>
                setSourceInterfaceId(
                  event.target.value
                )
              }
              className="w-full rounded-lg border border-white/10 bg-[#0b0d10] px-3 py-2.5 text-sm text-white outline-none"
            >
              {sourceInterfaces.length ===
              0 ? (
                <option value="">
                  No interfaces
                  defined
                </option>
              ) : (
                sourceInterfaces.map(
                  (item) => (
                    <option
                      key={item.id}
                      value={item.id}
                    >
                      {item.name} ·{" "}
                      {item.type}
                    </option>
                  )
                )
              )}
            </select>
          </div>

          {/* Target interface */}

          <div>
            <label className="mb-2 block text-sm text-white/60">
              Target Interface
            </label>

            <select
              value={
                targetInterfaceId
              }
              onChange={(event) =>
                setTargetInterfaceId(
                  event.target.value
                )
              }
              className="w-full rounded-lg border border-white/10 bg-[#0b0d10] px-3 py-2.5 text-sm text-white outline-none"
            >
              {targetInterfaces.length ===
              0 ? (
                <option value="">
                  No interfaces
                  defined
                </option>
              ) : (
                targetInterfaces.map(
                  (item) => (
                    <option
                      key={item.id}
                      value={item.id}
                    >
                      {item.name} ·{" "}
                      {item.type}
                    </option>
                  )
                )
              )}
            </select>
          </div>

          {/* Connection type */}

          <div>
            <label className="mb-2 block text-sm text-white/60">
              Connection Type
            </label>

            <select
              value={type}
              onChange={(event) =>
                setType(
                  event.target
                    .value as ConnectionType
                )
              }
              className="w-full rounded-lg border border-white/10 bg-[#0b0d10] px-3 py-2.5 text-sm text-white outline-none"
            >
              <option value="power">
                Power
              </option>

              <option value="communication">
                Communication
              </option>

              <option value="sensor_data">
                Sensor Data
              </option>

              <option value="control">
                Control
              </option>

              <option value="mechanical">
                Mechanical
              </option>

              <option value="thermal">
                Thermal
              </option>
            </select>
          </div>

          {/* Protocol */}

          <div>
            <label className="mb-2 block text-sm text-white/60">
              Protocol / Interface
            </label>

            <input
              value={protocol}
              onChange={(event) =>
                setProtocol(
                  event.target.value
                )
              }
              placeholder="USB 3.2, CAN, Ethernet, 24V DC..."
              className="w-full rounded-lg border border-white/10 bg-[#0b0d10] px-3 py-2.5 text-sm text-white outline-none placeholder:text-white/25"
            />
          </div>

          {/* Description */}

          <div>
            <label className="mb-2 block text-sm text-white/60">
              Description
            </label>

            <textarea
              value={description}
              onChange={(event) =>
                setDescription(
                  event.target.value
                )
              }
              placeholder="What information, energy, or force flows through this connection?"
              rows={3}
              className="w-full resize-none rounded-lg border border-white/10 bg-[#0b0d10] px-3 py-2.5 text-sm text-white outline-none placeholder:text-white/25"
            />
          </div>

          <div className="flex justify-end gap-2 border-t border-white/10 pt-5">
            <button
              type="button"
              onClick={onClose}
              className="rounded-lg px-4 py-2 text-sm text-white/50 hover:bg-white/5 hover:text-white"
            >
              Cancel
            </button>

            <button
              type="submit"
              className="rounded-lg bg-white px-4 py-2 text-sm font-medium text-black hover:bg-white/90"
            >
              {isEditing
                ? "Save Changes"
                : "Create Connection"}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}