"use client";

import {
  FormEvent,
  useEffect,
  useState,
} from "react";

import type {
  InterfaceDirection,
  InterfaceType,
  SystemInterface,
  SystemNodeData,
  SystemParameter,
} from "./SystemNode";

interface SystemModalProps {
  open: boolean;
  initialData?: SystemNodeData;
  onClose: () => void;
  onSubmit: (
    data: SystemNodeData
  ) => void;
}

const categories = [
  "Subsystem",
  "Mechanical",
  "Electrical",
  "Power",
  "Computing",
  "Sensors",
  "Control",
  "Software",
  "Thermal",
  "Other",
];

const statuses = [
  "Concept",
  "Designed",
  "Validated",
  "Manufacturing",
] as const;

const interfaceTypes: {
  value: InterfaceType;
  label: string;
}[] = [
  {
    value: "usb_c",
    label: "USB-C",
  },
  {
    value: "usb_a",
    label: "USB-A",
  },
  {
    value: "thunderbolt_3",
    label: "Thunderbolt 3",
  },
  {
    value: "thunderbolt_4",
    label: "Thunderbolt 4",
  },
  {
    value: "thunderbolt_5",
    label: "Thunderbolt 5",
  },
  {
    value: "ethernet",
    label: "Ethernet / RJ45",
  },
  {
    value: "hdmi",
    label: "HDMI",
  },
  {
    value: "displayport",
    label: "DisplayPort",
  },
  {
    value: "can",
    label: "CAN",
  },
  {
    value: "gpio",
    label: "GPIO",
  },
  {
    value: "power",
    label: "Power",
  },
  {
    value: "dc_power",
    label: "DC Power",
  },
  {
    value: "sfp",
    label: "SFP",
  },
  {
    value: "rs232",
    label: "RS-232",
  },
  {
    value: "rs485",
    label: "RS-485",
  },
  {
    value: "wifi",
    label: "Wi-Fi",
  },
  {
    value: "bluetooth",
    label: "Bluetooth",
  },
  {
    value: "cellular",
    label: "Cellular",
  },
  {
    value: "custom",
    label: "Custom",
  },
];

function createInterface(): SystemInterface {
  return {
    id: crypto.randomUUID(),
    name: "",
    direction: "bidirectional",
    type: "custom",
    standard: "",
    protocol: "",
    dataRate: "",
    voltage: "",
    maxCurrent: "",
    description: "",
  };
}

export default function SystemModal({
  open,
  initialData,
  onClose,
  onSubmit,
}: SystemModalProps) {
  const [label, setLabel] =
    useState("");

  const [category, setCategory] =
    useState("Subsystem");

  const [description, setDescription] =
    useState("");

  const [status, setStatus] =
    useState<
      SystemNodeData["status"]
    >("Concept");

  const [parameters, setParameters] =
    useState<SystemParameter[]>(
      []
    );

  const [interfaces, setInterfaces] =
    useState<SystemInterface[]>(
      []
    );

  useEffect(() => {
    if (!open) return;

    setLabel(
      initialData?.label ?? ""
    );

    setCategory(
      initialData?.category ??
        "Subsystem"
    );

    setDescription(
      initialData?.description ?? ""
    );

    setStatus(
      initialData?.status ??
        "Concept"
    );

    setParameters(
      initialData?.parameters ?? []
    );

    setInterfaces(
      initialData?.interfaces ?? []
    );
  }, [open, initialData]);

  if (!open) return null;

  function addParameter() {
    setParameters((current) => [
      ...current,
      {
        id: crypto.randomUUID(),
        name: "",
        value: "",
        unit: "",
      },
    ]);
  }

  function updateParameter(
    index: number,
    field: keyof SystemParameter,
    value: string
  ) {
    setParameters((current) =>
      current.map(
        (
          parameter,
          parameterIndex
        ) =>
          parameterIndex === index
            ? {
                ...parameter,
                [field]: value,
              }
            : parameter
      )
    );
  }

  function removeParameter(
    index: number
  ) {
    setParameters((current) =>
      current.filter(
        (_, parameterIndex) =>
          parameterIndex !== index
      )
    );
  }

  function addInterface() {
    setInterfaces((current) => [
      ...current,
      createInterface(),
    ]);
  }

  function updateInterface(
    index: number,
    field: keyof SystemInterface,
    value: string
  ) {
    setInterfaces((current) =>
      current.map(
        (
          interfaceItem,
          interfaceIndex
        ) =>
          interfaceIndex === index
            ? {
                ...interfaceItem,
                [field]: value,
              }
            : interfaceItem
      )
    );
  }

  function removeInterface(
    index: number
  ) {
    setInterfaces((current) =>
      current.filter(
        (_, interfaceIndex) =>
          interfaceIndex !== index
      )
    );
  }

  function handleSubmit(
    event: FormEvent
  ) {
    event.preventDefault();

    if (!label.trim()) return;

    onSubmit({
      ...initialData,

      label: label.trim(),

      category,

      description:
        description.trim(),

      status,

      parameters,

      interfaces,
    });
  }

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 p-4 backdrop-blur-sm"
      onMouseDown={(event) => {
        if (
          event.target ===
          event.currentTarget
        ) {
          onClose();
        }
      }}
    >
      <div className="max-h-[90vh] w-full max-w-3xl overflow-y-auto rounded-2xl border border-white/10 bg-[#111419] shadow-2xl">

        <div className="flex items-center justify-between border-b border-white/10 px-6 py-4">
          <div>
            <h2 className="text-lg font-semibold text-white">
              {initialData
                ? "Edit System"
                : "Add System"}
            </h2>

            <p className="mt-1 text-xs text-white/40">
              Define the engineering
              system, interfaces, and
              properties.
            </p>
          </div>

          <button
            type="button"
            onClick={onClose}
            className="rounded-lg px-2 py-1 text-white/40 hover:bg-white/10 hover:text-white"
          >
            ×
          </button>
        </div>

        <form
          onSubmit={handleSubmit}
          className="space-y-6 p-6"
        >
          {/* System information */}

          <div>
            <label className="mb-2 block text-sm text-white/60">
              System Name
            </label>

            <input
              autoFocus
              value={label}
              onChange={(event) =>
                setLabel(
                  event.target.value
                )
              }
              placeholder="e.g. Jetson Orin NX"
              className="w-full rounded-lg border border-white/10 bg-[#0b0d10] px-3 py-2.5 text-sm text-white outline-none placeholder:text-white/25 focus:border-white/30"
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="mb-2 block text-sm text-white/60">
                Category
              </label>

              <select
                value={category}
                onChange={(event) =>
                  setCategory(
                    event.target.value
                  )
                }
                className="w-full rounded-lg border border-white/10 bg-[#0b0d10] px-3 py-2.5 text-sm text-white outline-none focus:border-white/30"
              >
                {categories.map(
                  (item) => (
                    <option
                      key={item}
                      value={item}
                    >
                      {item}
                    </option>
                  )
                )}
              </select>
            </div>

            <div>
              <label className="mb-2 block text-sm text-white/60">
                Status
              </label>

              <select
                value={status}
                onChange={(event) =>
                  setStatus(
                    event.target
                      .value as SystemNodeData["status"]
                  )
                }
                className="w-full rounded-lg border border-white/10 bg-[#0b0d10] px-3 py-2.5 text-sm text-white outline-none focus:border-white/30"
              >
                {statuses.map(
                  (item) => (
                    <option
                      key={item}
                      value={item}
                    >
                      {item}
                    </option>
                  )
                )}
              </select>
            </div>
          </div>

          <div>
            <label className="mb-2 block text-sm text-white/60">
              Description
            </label>

            <textarea
              value={description}
              onChange={(event) =>
                setDescription(
                  event.target.value
                )
              }
              placeholder="What does this system do?"
              rows={3}
              className="w-full resize-none rounded-lg border border-white/10 bg-[#0b0d10] px-3 py-2.5 text-sm text-white outline-none placeholder:text-white/25"
            />
          </div>

          {/* Parameters */}

          <div>
            <div className="mb-2 flex items-center justify-between">
              <label className="text-sm text-white/60">
                Parameters
              </label>

              <button
                type="button"
                onClick={addParameter}
                className="rounded-md px-2 py-1 text-xs text-white/50 hover:bg-white/10 hover:text-white"
              >
                + Add Parameter
              </button>
            </div>

            {parameters.length ===
            0 ? (
              <div className="rounded-lg border border-dashed border-white/10 px-4 py-5 text-center text-xs text-white/30">
                No parameters defined.
              </div>
            ) : (
              <div className="space-y-2">
                {parameters.map(
                  (
                    parameter,
                    index
                  ) => (
                    <div
                      key={
                        parameter.id ??
                        `parameter-${index}`
                      }
                      className="grid grid-cols-[1fr_1fr_80px_32px] gap-2"
                    >
                      <input
                        value={
                          parameter.name
                        }
                        onChange={(
                          event
                        ) =>
                          updateParameter(
                            index,
                            "name",
                            event.target
                              .value
                          )
                        }
                        placeholder="Name"
                        className="rounded-lg border border-white/10 bg-[#0b0d10] px-3 py-2 text-xs text-white outline-none placeholder:text-white/25"
                      />

                      <input
                        value={
                          parameter.value
                        }
                        onChange={(
                          event
                        ) =>
                          updateParameter(
                            index,
                            "value",
                            event.target
                              .value
                          )
                        }
                        placeholder="Value"
                        className="rounded-lg border border-white/10 bg-[#0b0d10] px-3 py-2 text-xs text-white outline-none placeholder:text-white/25"
                      />

                      <input
                        value={
                          parameter.unit ??
                          ""
                        }
                        onChange={(
                          event
                        ) =>
                          updateParameter(
                            index,
                            "unit",
                            event.target
                              .value
                          )
                        }
                        placeholder="Unit"
                        className="rounded-lg border border-white/10 bg-[#0b0d10] px-3 py-2 text-xs text-white outline-none placeholder:text-white/25"
                      />

                      <button
                        type="button"
                        onClick={() =>
                          removeParameter(
                            index
                          )
                        }
                        className="rounded-lg text-white/30 hover:bg-white/10 hover:text-white"
                      >
                        ×
                      </button>
                    </div>
                  )
                )}
              </div>
            )}
          </div>

          {/* Interfaces */}

          <div>
            <div className="mb-3 flex items-center justify-between">
              <div>
                <label className="text-sm text-white/60">
                  Interfaces
                </label>

                <p className="mt-1 text-xs text-white/30">
                  Define the physical and
                  logical interfaces available
                  on this system.
                </p>
              </div>

              <button
                type="button"
                onClick={addInterface}
                className="rounded-md px-2 py-1 text-xs text-white/50 hover:bg-white/10 hover:text-white"
              >
                + Add Interface
              </button>
            </div>

            {interfaces.length ===
            0 ? (
              <div className="rounded-lg border border-dashed border-white/10 px-4 py-6 text-center text-xs text-white/30">
                No interfaces defined.
              </div>
            ) : (
              <div className="space-y-3">
                {interfaces.map(
                  (
                    item,
                    index
                  ) => (
                    <div
                      key={item.id}
                      className="rounded-xl border border-white/10 bg-[#0b0d10] p-4"
                    >
                      <div className="mb-3 flex items-center justify-between">
                        <span className="text-xs font-medium text-white/50">
                          Interface{" "}
                          {index + 1}
                        </span>

                        <button
                          type="button"
                          onClick={() =>
                            removeInterface(
                              index
                            )
                          }
                          className="rounded-md px-2 py-1 text-xs text-white/30 hover:bg-white/10 hover:text-white"
                        >
                          Remove
                        </button>
                      </div>

                      <div className="grid grid-cols-2 gap-3">
                        <input
                          value={
                            item.name
                          }
                          onChange={(
                            event
                          ) =>
                            updateInterface(
                              index,
                              "name",
                              event.target
                                .value
                            )
                          }
                          placeholder="Interface name"
                          className="rounded-lg border border-white/10 bg-[#15191f] px-3 py-2 text-xs text-white outline-none placeholder:text-white/25"
                        />

                        <select
                          value={
                            item.direction
                          }
                          onChange={(
                            event
                          ) =>
                            updateInterface(
                              index,
                              "direction",
                              event.target
                                .value as InterfaceDirection
                            )
                          }
                          className="rounded-lg border border-white/10 bg-[#15191f] px-3 py-2 text-xs text-white outline-none"
                        >
                          <option value="input">
                            Input
                          </option>

                          <option value="output">
                            Output
                          </option>

                          <option value="bidirectional">
                            Bidirectional
                          </option>
                        </select>

                        <select
                          value={
                            item.type
                          }
                          onChange={(
                            event
                          ) =>
                            updateInterface(
                              index,
                              "type",
                              event.target
                                .value as InterfaceType
                            )
                          }
                          className="rounded-lg border border-white/10 bg-[#15191f] px-3 py-2 text-xs text-white outline-none"
                        >
                          {interfaceTypes.map(
                            (
                              type
                            ) => (
                              <option
                                key={
                                  type.value
                                }
                                value={
                                  type.value
                                }
                              >
                                {
                                  type.label
                                }
                              </option>
                            )
                          )}
                        </select>

                        <input
                          value={
                            item.standard
                          }
                          onChange={(
                            event
                          ) =>
                            updateInterface(
                              index,
                              "standard",
                              event.target
                                .value
                            )
                          }
                          placeholder="Standard e.g. USB 3.2 Gen 2"
                          className="rounded-lg border border-white/10 bg-[#15191f] px-3 py-2 text-xs text-white outline-none placeholder:text-white/25"
                        />

                        <input
                          value={
                            item.protocol
                          }
                          onChange={(
                            event
                          ) =>
                            updateInterface(
                              index,
                              "protocol",
                              event.target
                                .value
                            )
                          }
                          placeholder="Protocol e.g. USB"
                          className="rounded-lg border border-white/10 bg-[#15191f] px-3 py-2 text-xs text-white outline-none placeholder:text-white/25"
                        />

                        <input
                          value={
                            item.dataRate
                          }
                          onChange={(
                            event
                          ) =>
                            updateInterface(
                              index,
                              "dataRate",
                              event.target
                                .value
                            )
                          }
                          placeholder="Data rate e.g. 10 Gb/s"
                          className="rounded-lg border border-white/10 bg-[#15191f] px-3 py-2 text-xs text-white outline-none placeholder:text-white/25"
                        />

                        <input
                          value={
                            item.voltage
                          }
                          onChange={(
                            event
                          ) =>
                            updateInterface(
                              index,
                              "voltage",
                              event.target
                                .value
                            )
                          }
                          placeholder="Voltage e.g. 5 V"
                          className="rounded-lg border border-white/10 bg-[#15191f] px-3 py-2 text-xs text-white outline-none placeholder:text-white/25"
                        />

                        <input
                          value={
                            item.maxCurrent
                          }
                          onChange={(
                            event
                          ) =>
                            updateInterface(
                              index,
                              "maxCurrent",
                              event.target
                                .value
                            )
                          }
                          placeholder="Max current e.g. 3 A"
                          className="rounded-lg border border-white/10 bg-[#15191f] px-3 py-2 text-xs text-white outline-none placeholder:text-white/25"
                        />

                        <input
                          value={
                            item.description
                          }
                          onChange={(
                            event
                          ) =>
                            updateInterface(
                              index,
                              "description",
                              event.target
                                .value
                            )
                          }
                          placeholder="Description"
                          className="rounded-lg border border-white/10 bg-[#15191f] px-3 py-2 text-xs text-white outline-none placeholder:text-white/25"
                        />
                      </div>
                    </div>
                  )
                )}
              </div>
            )}
          </div>

          <div className="flex justify-end gap-2 border-t border-white/10 pt-5">
            <button
              type="button"
              onClick={onClose}
              className="rounded-lg px-4 py-2 text-sm text-white/50 hover:bg-white/5 hover:text-white"
            >
              Cancel
            </button>

            <button
              type="submit"
              className="rounded-lg bg-white px-4 py-2 text-sm font-medium text-black hover:bg-white/90"
            >
              {initialData
                ? "Save Changes"
                : "Create System"}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}